# Requests made before the IT -> Survey Mitra -> Survey BC -> Safety flow.
OLD_STATUS = {
    'menunggu_digitasi': 'menunggu_mitra',
    'dikembalikan': 'return_it',
    'selesai': 'approved',
}
OLD_JENIS = {'dicabut': 'dipindah'}


def map_old_requests(apps, schema_editor):
    PengajuanCoverage = apps.get_model('cctv', 'PengajuanCoverage')
    for old, new in OLD_STATUS.items():
        PengajuanCoverage.objects.filter(status=old).update(status=new)
    for old, new in OLD_JENIS.items():
        PengajuanCoverage.objects.filter(jenis=old).update(jenis=new)


def give_it_bc_full_scope(apps, schema_editor):
    # Like the other IT roles (0002): every CCTV until an admin narrows it.
    Group = apps.get_model('auth', 'Group')
    CakupanCctv = apps.get_model('cctv', 'CakupanCctv')
    for group in Group.objects.filter(name='hazard-motion-it-bc'):
        CakupanCctv.objects.get_or_create(group=group, site=None, perusahaan=None, defaults={'bisa_ubah': True})


